import json
with open('/workspace/query1.json', 'r') as f:
    data = json.load(f)

by_lemma = {}
for entry in data:
    norm = entry['headword_norm']
    if norm not in by_lemma:
        by_lemma[norm] = []
    by_lemma[norm].append(entry)

for lemma, entries in by_lemma.items():
    print(f"Lemma: {lemma} ({len(entries)} entries)")
    for i, e in enumerate(entries[:5]):
        print(f"  [{e['entry_id']}] {e['headword']} ({e['dict_name_ar']}) -> {e['definitions_text'][:100]}...")
    if len(entries) > 5:
        print("  ...")
